create or replace function public.family_has_premium_access(p_user_id uuid default auth.uid()) returns boolean language sql stable security definer set search_path='' as $$ select p_user_id is not null and p_user_id=auth.uid() and exists(select 1 from public.family_members fm join public.family_groups fg on fg.id=fm.group_id join public.family_accounts fa on fa.owner_user_id=fg.owner_id where fm.user_id=p_user_id and fa.plan_code='family' and fa.max_members=5 and fg.max_members=5 and (select count(*) from public.family_members x where x.group_id=fm.group_id)<=5); $$; revoke all on function public.family_has_premium_access(uuid) from public,anon; grant execute on function public.family_has_premium_access(uuid) to authenticated;

create or replace function public.remove_family_member(p_member_id uuid) returns boolean language plpgsql security definer set search_path='public','auth','pg_temp' as $$ declare gid uuid; target_uid uuid; begin if auth.uid() is null then raise exception 'authentication required'; end if; select fm.group_id,fm.user_id into gid,target_uid from public.family_members fm join public.family_groups fg on fg.id=fm.group_id where fm.id=p_member_id and fg.owner_id=auth.uid(); if gid is null then raise exception 'family member not found'; end if; if target_uid=auth.uid() then raise exception 'owner cannot remove owner seat'; end if; delete from public.family_members where id=p_member_id; return found; end $$; revoke all on function public.remove_family_member(uuid) from public,anon; grant execute on function public.remove_family_member(uuid) to authenticated;

create or replace function public.leave_family_group() returns boolean language plpgsql security definer set search_path='public','auth','pg_temp' as $$ declare mid uuid; rel text; begin if auth.uid() is null then raise exception 'authentication required'; end if; select id,relationship into mid,rel from public.family_members where user_id=auth.uid() limit 1; if mid is null then return false; end if; if rel='owner' then raise exception 'family owner cannot leave; manage or end the Family subscription first'; end if; delete from public.family_members where id=mid; return found; end $$; revoke all on function public.leave_family_group() from public,anon; grant execute on function public.leave_family_group() to authenticated;

create or replace function public.cancel_family_invite(p_invite_id uuid) returns boolean language plpgsql security definer set search_path='public','auth','pg_temp' as $$ begin if auth.uid() is null then raise exception 'authentication required'; end if; update public.family_invites fi set status='cancelled' where fi.id=p_invite_id and fi.status='pending' and fi.invited_by=auth.uid() and exists(select 1 from public.family_groups fg where fg.id=fi.group_id and fg.owner_id=auth.uid()); return found; end $$; revoke all on function public.cancel_family_invite(uuid) from public,anon; grant execute on function public.cancel_family_invite(uuid) to authenticated;
